    pub swept: u64,
}

impl SweepRun {
    /// A pass completing now, having swept `swept` items.
    pub fn now(swept: u64) -> Self {
        Self {
            completed_at: chrono::Utc::now().timestamp(),
            swept,
        }
    }
}

