9	/**
10	 * Render a duration in seconds as a compact `uptime`-style figure: `47s` under a
11	 * minute, then the two largest units — `12m 3s`, `4h 12m`, `3d 4h`. Literal and
12	 * scannable; no rounding a day up to "1 week".
13	 */
14	export function formatDuration(seconds: number): string {
15	  const s = Math.max(0, Math.floor(seconds));
16	  if (s < 60) return `${s}s`;
17	  const units: [string, number][] = [
18	    ['d', 86_400],
19	    ['h', 3_600],
20	    ['m', 60],
21	    ['s', 1],
22	  ];
23	  const parts: string[] = [];
24	  let rest = s;
25	  for (const [name, size] of units) {
26	    const count = Math.floor(rest / size);
27	    if (count > 0 || parts.length > 0) {
28	      parts.push(`${count}${name}`);
29	      rest -= count * size;
30	    }
31	    if (parts.length === 2) break;
32	  }
33	  return parts.join(' ');
34	}
35	
36	/**
37	 * The firehose backfill window: how far back a reconnecting subscriber's cursor still
38	 * replays exactly. `null` means the event log is empty — say so literally rather than
39	 * rendering a zero that would read as "no window".
40	 */
41	export function formatBackfillWindow(seconds: number | null): string {
42	  if (seconds === null) return 'empty log';
43	  return formatDuration(seconds);
44	}
45	
46	/**
47	 * One background sweep's row on the Status screen.
48	 *
49	 * `run` is the sweep's last completed pass (`null` until its first pass after boot —
50	 * each sweep first runs one full interval after startup). A failed pass records
51	 * nothing, so a `completedAt` that keeps ageing IS the "sweeps are failing" signal —
52	 * this line is where that signal becomes visible to the operator.
53	 *
54	 * `nowSeconds` is the current unix time, passed in so the function stays pure.
55	 *
56	 * Contract (pinned by health.test.ts):
57	 * - Returns a single monospace-friendly line; status is carried by text/glyphs,
58	 *   never color (AAA).
59	 * - Must distinguish "never ran yet" from "ran, swept nothing" — a quiet sweep is
60	 *   healthy, a missing one may not be: `null` → `not yet run`, a completed pass →
61	 *   `<age> ago · swept <n>` (`4m ago · swept 7`; `swept 0` stays visible).
62	 * - Ages ≥ 24h earn a trailing ` !` (quotaBar's glyph-not-color convention). The
63	 *   relay doesn't report sweep intervals — prod sweeps run on minutes-to-hours
64	 *   cadences, so a full day without a completed pass is worth a marker on any of
65	 *   them, while never false-flagging a slow-but-healthy daily-ish sweep.
66	 */
67	export function sweepLine(run: SweepRun | null, nowSeconds: number): string {
68	  if (run === null) return 'not yet run';
69	  const age = Math.max(0, nowSeconds - run.completedAt);
70	  const stale = age >= 86_400 ? ' !' : '';
71	  return `${formatDuration(age)} ago · swept ${run.swept}${stale}`;
72	}
